renderPortal.source:
renderPortal({ beforeRender, afterRender } = {}) {
    if (this.open < 0.025 || this.traversed) return;
    this.mainCamera.updateMatrixWorld(true);
    this.group.updateMatrixWorld(true);
    const sourceSurface = this.visual.localToWorld(_center.set(0, 0, -this.depth));
    this.group.getWorldQuaternion(this.sourceQuaternion);
    this.sourceFrameMatrix.compose(sourceSurface, this.sourceQuaternion, this.unitScale);
    this.targetFrameMatrix.compose(this.targetAnchor, this.targetQuaternion, this.unitScale);
    this.inverseSourceMatrix.copy(this.sourceFrameMatrix).invert();
    this.offsetMatrix.copy(this.targetFrameMatrix).multiply(this.inverseSourceMatrix);
    this.portalCamera.position.copy(this.mainCamera.position).applyMatrix4(this.offsetMatrix);
    this.frameRotation.copy(this.targetQuaternion).multiply(this.sourceQuaternion.clone().invert());
    this.portalCamera.quaternion.copy(this.frameRotation).multiply(this.mainCamera.quaternion);
    this.portalCamera.scale.copy(this.mainCamera.scale);
    this.portalCamera.fov = this.mainCamera.fov;
    this.portalCamera.aspect = this.mainCamera.aspect;
    this.portalCamera.near = this.mainCamera.near;
    this.portalCamera.far = this.mainCamera.far;
    this.portalCamera.updateProjectionMatrix();
    this.portalCamera.updateMatrixWorld(true);
    // The destination atmosphere and volumetric cloud shell live on layer 2
    // in the main render graph. The portal is a direct offscreen render, so it
    // must opt into that same layer or the planet is shown bare until crossing.
    const oldLayerMask = this.portalCamera.layers.mask;
    const wasVisible = this.group.visible;
    const oldTarget = this.renderer.getRenderTarget();
    const oldFace = this.renderer.getActiveCubeFace(), oldMip = this.renderer.getActiveMipmapLevel();
    const oldXr = this.renderer.xr.enabled;
    const oldAutoClear = this.renderer.autoClear;
    let entered = false, rendered = false, failed = false, failure;
    const cleanup = work => {
      try { work(); } catch (error) { if (!failed) { failed = true; failure = error; } }
    };
    this.portalVolumeLayerRendered = false;
    try {
      this.portalCamera.layers.enable(2);
      const volumeLayer = this.portalCamera.layers.isEnabled(2);
      this.textureMatrix.copy(this.biasMatrix)
        .multiply(this.portalCamera.projectionMatrix)
        .multiply(this.portalCamera.matrixWorldInverse)
        .multiply(this.offsetMatrix);
      this.portalMat.uniforms.uTextureMatrix.value.copy(this.textureMatrix);
      this.group.visible = false;
      // A throwing before hook may already own scene/light state. Its matching
      // after hook still has to run, without replacing the original exception.
      entered = true;
      beforeRender?.(this.portalCamera);
      this.renderer.xr.enabled = false;
      this.renderer.setRenderTarget(this.portalRT);
      this.renderer.clear();
      this.renderer.render(this.scene, this.portalCamera);
      // The destination hook can remap the camera AND its volume meshes to a
      // private layer. Preserve the existing opt-in diagnostic on success.
      rendered = volumeLayer;
    } catch (error) {
      failed = true; failure = error;
    } finally {
      cleanup(() => this.renderer.setRenderTarget(oldTarget, oldFace, oldMip));
      cleanup(() => { this.renderer.xr.enabled = oldXr; });
      cleanup(() => { this.renderer.autoClear = oldAutoClear; });
      cleanup(() => { this.portalCamera.layers.mask = oldLayerMask; });
      if (entered) cleanup(() => afterRender?.());
      // Keep the normal after-hook view of the restored caller state, then
      // recover any borrowed state it changed before returning or throwing.
      cleanup(() => {
        if (this.renderer.getRenderTarget() !== oldTarget || this.renderer.getActiveCubeFace() !== oldFace
          || this.renderer.getActiveMipmapLevel() !== oldMip) this.renderer.setRenderTarget(oldTarget, oldFace, oldMip);
      });
      cleanup(() => { this.renderer.xr.enabled = oldXr; });
      cleanup(() => { this.renderer.autoClear = oldAutoClear; });
      cleanup(() => { this.portalCamera.layers.mask = oldLayerMask; });
      cleanup(() => { this.group.visible = wasVisible; });
    }
    this.portalVolumeLayerRendered = rendered && !failed;
    if (failed) throw failure;
  }

renderRiftDestinationPortal.source:
function renderRiftDestinationPortal({
  force = false,
  previewSystem = riftPreviewSystem,
  targetBodyId = riftRoute?.arrival?.bodyId || null,
} = {}) {
  spatialRift.renderPortal({
    force,
    beforeRender: (portalCamera) => {
      beginRiftPortalScene(portalCamera, previewSystem, targetBodyId);
    },
    renderScene: null,
    afterRender: () => endRiftPortalScene(previewSystem, targetBodyId),
  });
}

prewarmPreparedRiftPortal.source:
async function prewarmPreparedRiftPortal(targetBody, token, route, prepared) {
  if (!preparedDestinationIsActive(token, route, prepared) || route?.warpRequested) return;
  if (warpPreparedRiftWarmState === 'compiling'
      || warpPreparedRiftWarmState === 'complete') return;
  if (!targetBody?.group || !route?.target?.entry) {
    if (preparedDestinationIsActive(token, route, prepared)) {
      warpPreparedRiftWarmState = 'complete';
    }
    return;
  }
  warpPreparedRiftWarmState = 'compiling';
  try {
    await warpPreparedRiftStructurePromise;
    if (!preparedDestinationIsActive(token, route, prepared) || route.warpRequested) return;
    await uploadPreparedLodMeshes(targetBody, prepared, token, route);
    if (!preparedDestinationIsActive(token, route, prepared) || route.warpRequested) return;

    const signal = warpCompile.signal;
    await nodePipeline.prepare(() => {
      prepared.updateCelestial(celestialClock.hours);
      const cameraOffset = route.target.entry.clone().sub(targetBody.posUniv);
      targetBody.volumeActive = true;
      targetBody.volumeBlend = 1;
      targetBody.update(cameraOffset, 1 / 60, true, 0);
      if (targetBody.volCloudMesh) targetBody.volCloudMesh.visible = true;
      universe.relativizeSystem(prepared, route.target.entry);

      const sourceQuat = nav.quat.clone();
      const sourceForward = new THREE.Vector3(0, 0, -1).applyQuaternion(sourceQuat).normalize();
      const sourcePosition = nav.pos.clone().addScaledVector(sourceForward, RIFT_SPAWN_DISTANCE);
      const targetQuat = lookQuatAt(route.target.entry, route.target.center, new THREE.Quaternion());
      spatialRift.setTransform(
        sourcePosition.sub(nav.pos),
        sourceQuat,
        new THREE.Vector3(),
        targetQuat,
      );
      // compileAsync captures pipelines, but the first direct portal draw still
      // has to allocate attachments and execute the complete target-world pass.
      // Do that once while the passage is hidden so the opening animation never
      // exposes a cold WebGPU frame.
      renderRiftDestinationPortal({
        force: true,
        previewSystem: prepared,
        targetBodyId: route.bodyId,
        previewOrigin: route.target.entry,
      });
    }, { signal, label: 'destination-portal',
      isCurrent: () => preparedDestinationIsActive(token, route, prepared) && !route.warpRequested });
    if (!preparedDestinationIsActive(token, route, prepared) || route.warpRequested) return;
    await renderPreparedDestinationWarmFrame(targetBody, route, prepared, token);
    if (!preparedDestinationIsActive(token, route, prepared) || route.warpRequested) return;
    warpPreparedRiftWarmState = 'complete';
    warpPreparedRiftWarmError = null;
  } catch (error) {
    if (!preparedDestinationIsActive(token, route, prepared) || route.warpRequested) return;
    warpPreparedRiftWarmState = 'failed';
    warpPreparedRiftWarmError = String(error?.message || error);
    console.error('Destination portal pipeline prewarm failed:', error);
  }
}
